  ('remera-boxing-lunares', 'Remera Boxing con Lunares', 17999, 'Remeras', 'Remera oversized de algodón con lunares, corte boxy. Divertida, cómoda y con caída relajada.', array['Único']::text[], '[{"name":"Blanca","hex":"#f5f2ec","images":["https://flord-pilchasok.vercel.app/remera-boxing-lunares-blanca-front.webp","https://flord-pilchasok.vercel.app/remera-boxing-lunares-blanca-back.webp"]},{"name":"Negra","hex":"#111111","images":["https://flord-pilchasok.vercel.app/remera-boxing-lunares-negra-front.webp","https://flord-pilchasok.vercel.app/remera-boxing-lunares-negra-back.webp"]},{"name":"Marrón","hex":"#5c3a2a","images":["https://flord-pilchasok.vercel.app/remera-boxing-lunares-marron-front.webp"]},{"name":"Beige","hex":"#e8d5b5","images":["https://flord-pilchasok.vercel.app/remera-boxing-lunares-beige-front.webp"]}]'::jsonb, '{}'::text[], true, false, 30),
  ('vestido-india-largo', 'Vestido de la India Largo', 45000, 'Vestidos', 'Vestido largo de la India con estampa ikat, mangas con volado y falda amplia en capas. Fresco y con mucha caída.', array['L/XL']::text[], '[]'::jsonb, array['https://flord-pilchasok.vercel.app/vestido-india-largo.webp']::text[], true, false, 40),
  ('vestido-india-corto', 'Vestido de la India Corto', 40000, 'Vestidos', 'Vestido corto de la India con estampa de hojas en negro y crudo, borlas en el escote y volado en el ruedo.', array['L/XL']::text[], '[]'::jsonb, array['https://flord-pilchasok.vercel.app/vestido-india-corto.webp']::text[], true, false, 50)
on conflict (id) do update set
  name = excluded.name, price = excluded.price, category = excluded.category,
  description = excluded.description, sizes = excluded.sizes, colors = excluded.colors,
  images = excluded.images, active = excluded.active, sold_out = excluded.sold_out, sort = excluded.sort;

select id, name, price, sort from public.products order by sort;
